import unittest
import sizes


class TestParseSize(unittest.TestCase):

    def test_valid_integer_sizes(self):
        self.assertEqual(sizes.parse_size("512B"), 512)
        self.assertEqual(sizes.parse_size("4KB"), 4096)
        self.assertEqual(sizes.parse_size("1MB"), 1048576)
        self.assertEqual(sizes.parse_size("2GB"), 2147483648)

    def test_valid_zero_sizes(self):
        self.assertEqual(sizes.parse_size("0B"), 0)
        self.assertEqual(sizes.parse_size("0KB"), 0)
        self.assertEqual(sizes.parse_size("0MB"), 0)
        self.assertEqual(sizes.parse_size("0GB"), 0)
        self.assertEqual(sizes.parse_size("0.0B"), 0)

    def test_valid_fractional_sizes(self):
        self.assertEqual(sizes.parse_size("1.5KB"), 1536)
        self.assertEqual(sizes.parse_size("1.5MB"), 1572864)
        self.assertEqual(sizes.parse_size("0.5GB"), 536870912)

    def test_fractional_rounds_down_to_whole_bytes(self):
        self.assertEqual(sizes.parse_size("0.5B"), 0)
        self.assertEqual(sizes.parse_size("1.9B"), 1)
        self.assertEqual(sizes.parse_size("1.0005KB"), 1024)

    def test_return_type_is_int(self):
        result = sizes.parse_size("512B")
        self.assertIs(type(result), int)

    def test_missing_unit_raises_value_error(self):
        for invalid_input in ("", "512", "1.5"):
            with self.subTest(invalid_input=invalid_input):
                with self.assertRaises(ValueError):
                    sizes.parse_size(invalid_input)

    def test_missing_number_raises_value_error(self):
        for invalid_input in ("B", "KB", "MB", "GB"):
            with self.subTest(invalid_input=invalid_input):
                with self.assertRaises(ValueError):
                    sizes.parse_size(invalid_input)

    def test_case_sensitive_units_raises_value_error(self):
        for invalid_input in (
            "512b", "4kb", "4Kb", "4kB", "1mb", "1Mb", "1mB", "2gb", "2Gb", "2gB"
        ):
            with self.subTest(invalid_input=invalid_input):
                with self.assertRaises(ValueError):
                    sizes.parse_size(invalid_input)

    def test_unsupported_units_raises_value_error(self):
        for invalid_input in ("1TB", "4KiB", "512bytes", "4K", "1M", "2G"):
            with self.subTest(invalid_input=invalid_input):
                with self.assertRaises(ValueError):
                    sizes.parse_size(invalid_input)

    def test_negative_numbers_raises_value_error(self):
        for invalid_input in ("-1B", "-4KB", "-1.5MB", "-0B"):
            with self.subTest(invalid_input=invalid_input):
                with self.assertRaises(ValueError):
                    sizes.parse_size(invalid_input)

    def test_whitespace_raises_value_error(self):
        for invalid_input in (" 4KB", "4KB ", "4 KB", "\t4KB", "4KB\n", "1 .5MB"):
            with self.subTest(invalid_input=invalid_input):
                with self.assertRaises(ValueError):
                    sizes.parse_size(invalid_input)

    def test_other_characters_raises_value_error(self):
        for invalid_input in ("+4KB", "1_024B", "1.2.3MB", "1e3KB", "1,5MB"):
            with self.subTest(invalid_input=invalid_input):
                with self.assertRaises(ValueError):
                    sizes.parse_size(invalid_input)

    def test_non_ascii_digits_raises_value_error(self):
        for invalid_input in ("１KB", "١MB"):
            with self.subTest(invalid_input=invalid_input):
                with self.assertRaises(ValueError):
                    sizes.parse_size(invalid_input)


if __name__ == "__main__":
    unittest.main()

