import unittest
import cells


class TestParseCell(unittest.TestCase):
    def test_docstring_examples(self):
        self.assertEqual(cells.parse_cell("B3"), (2, 3))
        self.assertEqual(cells.parse_cell("AA10"), (27, 10))

    def test_return_type_is_tuple(self):
        result = cells.parse_cell("A1")
        self.assertIs(type(result), tuple)

    def test_valid_single_letter_columns_edges(self):
        self.assertEqual(cells.parse_cell("A1"), (1, 1))
        self.assertEqual(cells.parse_cell("B1"), (2, 1))
        self.assertEqual(cells.parse_cell("Z1"), (26, 1))

    def test_valid_two_letter_columns_edges(self):
        self.assertEqual(cells.parse_cell("AA1"), (27, 1))
        self.assertEqual(cells.parse_cell("AB1"), (28, 1))
        self.assertEqual(cells.parse_cell("AZ1"), (52, 1))
        self.assertEqual(cells.parse_cell("BA1"), (53, 1))
        self.assertEqual(cells.parse_cell("ZZ1"), (702, 1))
        self.assertEqual(cells.parse_cell("ZZ702"), (702, 702))

    def test_valid_multi_digit_row(self):
        self.assertEqual(cells.parse_cell("A99"), (1, 99))
        self.assertEqual(cells.parse_cell("AA1000"), (27, 1000))

    def test_invalid_empty_string(self):
        with self.assertRaises(ValueError):
            cells.parse_cell("")

    def test_invalid_lowercase_letters(self):
        for invalid in ("a1", "b3", "aa10", "Aa1", "aA1", "z1", "zz1"):
            with self.assertRaises(ValueError):
                cells.parse_cell(invalid)

    def test_invalid_column_more_than_two_letters(self):
        for invalid in ("AAA1", "ABC10", "ZZZ1"):
            with self.assertRaises(ValueError):
                cells.parse_cell(invalid)

    def test_invalid_missing_column(self):
        for invalid in ("1", "10", "999"):
            with self.assertRaises(ValueError):
                cells.parse_cell(invalid)

    def test_invalid_non_ascii_letters(self):
        for invalid in ("É1", "Ω1", "А1"):
            with self.assertRaises(ValueError):
                cells.parse_cell(invalid)

    def test_invalid_missing_row(self):
        for invalid in ("A", "B", "Z", "AA", "ZZ"):
            with self.assertRaises(ValueError):
                cells.parse_cell(invalid)

    def test_invalid_row_zero(self):
        for invalid in ("A0", "AA0", "Z0"):
            with self.assertRaises(ValueError):
                cells.parse_cell(invalid)

    def test_invalid_row_negative(self):
        for invalid in ("A-1", "AA-10", "Z-5"):
            with self.assertRaises(ValueError):
                cells.parse_cell(invalid)

    def test_invalid_row_leading_zeros(self):
        for invalid in ("A01", "A001", "AA01", "AA010", "B03"):
            with self.assertRaises(ValueError):
                cells.parse_cell(invalid)

    def test_invalid_whitespace(self):
        for invalid in (" A1", "A1 ", "A 1", "AA 10", "\tA1", "A1\n", " "):
            with self.assertRaises(ValueError):
                cells.parse_cell(invalid)

    def test_invalid_other_characters(self):
        for invalid in ("$A1", "A$1", "$A$1", "A#1", "A_1", "A+1", "A.1", "A!1", "A1.5"):
            with self.assertRaises(ValueError):
                cells.parse_cell(invalid)

    def test_invalid_order_or_extra_characters(self):
        for invalid in ("A1A", "B3b", "AA10X", "1A", "10AA"):
            with self.assertRaises(ValueError):
                cells.parse_cell(invalid)


if __name__ == "__main__":
    unittest.main()

