import unittest
import kvpairs


class TestParseKv(unittest.TestCase):
    def test_example(self):
        self.assertEqual(kvpairs.parse_kv("a=1;b=two"), {"a": "1", "b": "two"})

    def test_single_pair(self):
        self.assertEqual(kvpairs.parse_kv("k=v"), {"k": "v"})

    def test_valid_key_characters(self):
        self.assertEqual(kvpairs.parse_kv("aZ_09=value"), {"aZ_09": "value"})

    def test_empty_string(self):
        self.assertEqual(kvpairs.parse_kv(""), {})

    def test_all_whitespace_string(self):
        self.assertEqual(kvpairs.parse_kv("   \t \n "), {})

    def test_whitespace_around_keys_and_values_stripped(self):
        self.assertEqual(
            kvpairs.parse_kv("  k1  =  v1  ;  k2  =  v2  "),
            {"k1": "v1", "k2": "v2"},
        )

    def test_empty_value(self):
        self.assertEqual(kvpairs.parse_kv("key="), {"key": ""})

    def test_empty_value_with_whitespace(self):
        self.assertEqual(kvpairs.parse_kv("key=   "), {"key": ""})

    def test_value_with_equals(self):
        self.assertEqual(kvpairs.parse_kv("k=a=b=c"), {"k": "a=b=c"})

    def test_value_with_other_characters(self):
        self.assertEqual(
            kvpairs.parse_kv("k=hello world!@#$%^&*()_+{}|:\"<>?~`[]\\',./"),
            {"k": "hello world!@#$%^&*()_+{}|:\"<>?~`[]\\',./"},
        )

    def test_missing_equals_raises_value_error(self):
        with self.assertRaises(ValueError):
            kvpairs.parse_kv("invalid")
        with self.assertRaises(ValueError):
            kvpairs.parse_kv("a=1;b")

    def test_empty_key_raises_value_error(self):
        with self.assertRaises(ValueError):
            kvpairs.parse_kv("=value")
        with self.assertRaises(ValueError):
            kvpairs.parse_kv("   =value")

    def test_invalid_key_characters_raise_value_error(self):
        with self.assertRaises(ValueError):
            kvpairs.parse_kv("a-b=1")
        with self.assertRaises(ValueError):
            kvpairs.parse_kv("a b=1")
        with self.assertRaises(ValueError):
            kvpairs.parse_kv("a.b=1")
        with self.assertRaises(ValueError):
            kvpairs.parse_kv("këy=1")

    def test_duplicate_key_raises_value_error(self):
        with self.assertRaises(ValueError):
            kvpairs.parse_kv("a=1;a=2")
        with self.assertRaises(ValueError):
            kvpairs.parse_kv("a=1; a=2")


if __name__ == "__main__":
    unittest.main()

