import unittest
import roman


class TestRomanToInt(unittest.TestCase):
    def test_single_characters(self):
        cases = {
            "I": 1,
            "V": 5,
            "X": 10,
            "L": 50,
            "C": 100,
            "D": 500,
            "M": 1000,
        }
        for s, expected in cases.items():
            self.assertEqual(roman.roman_to_int(s), expected)

    def test_edge_values(self):
        self.assertEqual(roman.roman_to_int("I"), 1)
        self.assertEqual(roman.roman_to_int("MMMCMXCIX"), 3999)

    def test_repetition_up_to_three(self):
        cases = {
            "II": 2,
            "III": 3,
            "XX": 20,
            "XXX": 30,
            "CC": 200,
            "CCC": 300,
            "MM": 2000,
            "MMM": 3000,
        }
        for s, expected in cases.items():
            self.assertEqual(roman.roman_to_int(s), expected)

    def test_canonical_subtractive_pairs(self):
        pairs = {
            "IV": 4,
            "IX": 9,
            "XL": 40,
            "XC": 90,
            "CD": 400,
            "CM": 900,
        }
        for s, expected in pairs.items():
            self.assertEqual(roman.roman_to_int(s), expected)

    def test_representative_complex_canonical_values(self):
        cases = {
            "LVIII": 58,
            "CDXLIV": 444,
            "MCMXCIV": 1994,
            "MMXXIV": 2024,
            "MMMDCCCLXXXVIII": 3888,
        }
        for s, expected in cases.items():
            self.assertEqual(roman.roman_to_int(s), expected)

    def test_empty_string_raises_value_error(self):
        with self.assertRaises(ValueError):
            roman.roman_to_int("")

    def test_lowercase_letters_raise_value_error(self):
        for s in ["i", "v", "x", "l", "c", "d", "m", "iv", "ix", "mcmxciv"]:
            with self.assertRaises(ValueError):
                roman.roman_to_int(s)

    def test_invalid_characters_raise_value_error(self):
        for s in ["A", "1", " ", "IV ", " XIV", "X-I", "XVI."]:
            with self.assertRaises(ValueError):
                roman.roman_to_int(s)

    def test_more_than_three_identical_letters_in_a_row_raises_value_error(self):
        for s in ["IIII", "XXXX", "CCCC", "MMMM", "VIIII", "MCCCC"]:
            with self.assertRaises(ValueError):
                roman.roman_to_int(s)

    def test_repeating_v_l_d_raises_value_error(self):
        for s in ["VV", "LL", "DD", "VIV", "LXL", "DCD", "XVV", "XLL"]:
            with self.assertRaises(ValueError):
                roman.roman_to_int(s)

    def test_disallowed_subtractive_pairs_raise_value_error(self):
        disallowed = [
            "IL", "IC", "ID", "IM",
            "VX", "VL", "VC", "VD", "VM",
            "XD", "XM",
            "LC", "LD", "LM",
            "DM",
        ]
        for s in disallowed:
            with self.assertRaises(ValueError):
                roman.roman_to_int(s)

    def test_multiple_subtractive_prefixes_raise_value_error(self):
        for s in ["IIV", "IIX", "XXL", "XXC", "CCD", "CCM"]:
            with self.assertRaises(ValueError):
                roman.roman_to_int(s)


if __name__ == "__main__":
    unittest.main()

